// HasRunAttribution applies the HasEdge predicate on the "run_attribution" edge.
func HasRunAttribution() predicate.UsageEvent {
	return predicate.UsageEvent(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RunAttributionTable, RunAttributionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRunAttributionWith applies the HasEdge predicate on the "run_attribution" edge with a given conditions (other predicates).
func HasRunAttributionWith(preds ...predicate.RunAttribution) predicate.UsageEvent {
	return predicate.UsageEvent(func(s *sql.Selector) {
		step := newRunAttributionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UsageEvent) predicate.UsageEvent {
	return predicate.UsageEvent(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UsageEvent) predicate.UsageEvent {
	return predicate.UsageEvent(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UsageEvent) predicate.UsageEvent {
	return predicate.UsageEvent(sql.NotPredicates(p))
}
